// components/Navbar.jsx
import { Link } from "react-router-dom";
import { useContext } from 'react';
import { AuthContext } from '../context/AuthContext';

function Navbar() {
  const { user, logout } = useContext(AuthContext);

  return (
    <header className="site-nav">
      <div className="site-brand"><Link to="/">ReviewCommunity</Link></div>
      <div className="links">
        <Link to="/">오늘의 하루</Link>
        {/* 클릭 시 Home에서 리뷰 섹션을 보여주기 위해 쿼리 파라미터를 전달 */}
        <Link to="/?view=reviews">리뷰</Link>
        <Link to="/magazine">A</Link>
        <Link to="/coupons">쿠폰센터</Link>
        <Link to="/roulette">룰렛</Link>
        <Link to="/profile">프로필</Link>
        {user ? (
          <button onClick={logout} className="btn" style={{ marginLeft: 12 }}>로그아웃</button>
        ) : (
          <>
            <Link to="/login" style={{ marginLeft: 12 }}>로그인</Link>
            <Link to="/register" style={{ marginLeft: 8 }}>회원가입</Link>
          </>
        )}
      </div>
    </header>
  );
}

export default Navbar;
